package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.mockito.ArgumentMatchers.*;
import com.lianxibu.site.repository.jobs.*;
import java.sql.Timestamp;
import org.junit.jupiter.api.Test;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;

/** Actual opaque original P2 and P1 writer authority; only owned fictional databases. */
class SourceValuePartialCommitPermitTest {
    SourceValuePartialSealTest q;SourceValuePartialResolutionTest f;JdbcSourceValuePartialBlocks blocks;JdbcSourceStageRoots roots;SourceValuePartialCommitPermitService service;
    GenerationJdbcStoreTest database(){return new GenerationJdbcStoreTest();}
    void setup(boolean mixed)throws Exception{q=new SourceValuePartialSealTest(){@Override GenerationJdbcStoreTest database(){return SourceValuePartialCommitPermitTest.this.database();}};q.setup(mixed,false);f=q.p.f;blocks=new JdbcSourceValuePartialBlocks(f.db.source);roots=new JdbcSourceStageRoots(f.db.source);service=provider(f.authority.service);}
    SourceValuePartialCommitPermitService provider(SourceDedupPartialDependencyPermitService dedup){return new SourceValuePartialCommitPermitService(q.service,f.service,blocks,q.store,roots,dedup,new DataSourceTransactionManager(f.db.source));}
    SourceValueStageResult verify(SourceValuePartialCommitPermitService.Captured captured){return f.original.p1.tx(()->service.verify(captured));}
    @Test void ActualSealedOriginalPartsAndFailedDedupZeroValueGrantOnlyTheCurrentWriter()throws Exception{
        setup(true);assertNull(service.capture(f.ref));var seal=q.service.seal(f.ref);var captured=service.capture(f.ref);int rows=f.db.count("1=1"),calls=f.db.jdbc.queryForObject("SELECT SUM(call_count) FROM jobs",Integer.class);assertEquals(seal.proof().json(),captured.proof().json());assertEquals(seal.proof().json(),verify(captured).json());assertFalse(captured.toString().contains("Fictional"));assertEquals(rows,f.db.count("1=1"));assertEquals(calls,f.db.jdbc.queryForObject("SELECT SUM(call_count) FROM jobs",Integer.class));f.db.jdbc.execute("DROP TABLE source_run_items");f.db.jdbc.execute("DROP TABLE analyzed_entities");service=provider(f.authority.service);assertEquals(seal.proof().json(),verify(service.capture(f.ref)).json());
        setup(false);seal=q.service.seal(f.ref);captured=service.capture(f.ref);assertTrue(captured.proof().fragments().isEmpty());assertEquals(seal.proof().json(),verify(captured).json());assertEquals(0,f.db.count("record_kind='logical_task' AND task_type='news_value'"));
    }
    @Test void CapturedValueTimeDedupRevisionBlocksAndReceiptAreAllRechecked()throws Exception{
        setup(true);q.service.seal(f.ref);var captured=service.capture(f.ref);var nativeRoot=f.read().fragments().getFirst().nativeRoot();f.db.jdbc.update("UPDATE jobs SET updated_at=? WHERE id=?",Timestamp.from(nativeRoot.updatedAt().plusNanos(1000)),nativeRoot.id());assertThrows(RuntimeException.class,()->verify(captured));f.db.jdbc.update("UPDATE jobs SET updated_at=? WHERE id=?",Timestamp.from(nativeRoot.updatedAt()),nativeRoot.id());assertNotNull(verify(captured));String p1=f.authority.f.plan.chunks().getLast().rootId();long revision=f.db.jdbc.queryForObject("SELECT revision FROM jobs WHERE id=?",Long.class,p1);f.db.jdbc.update("UPDATE jobs SET revision=revision+1 WHERE id=?",p1);assertThrows(RuntimeException.class,()->verify(captured));f.db.jdbc.update("UPDATE jobs SET revision=? WHERE id=?",revision,p1);assertNotNull(verify(captured));String id=f.db.jdbc.queryForObject("SELECT id FROM jobs WHERE purpose='result' AND owner_job_id=? AND part_no=1",String.class,f.ref.ownerId());byte[] hash=f.db.jdbc.queryForObject("SELECT payload_hash FROM jobs WHERE id=?",byte[].class,id);f.db.jdbc.update("UPDATE jobs SET payload_hash=? WHERE id=?",new byte[32],id);assertThrows(RuntimeException.class,()->verify(captured));f.db.jdbc.update("UPDATE jobs SET payload_hash=? WHERE id=?",hash,id);String receipt=JdbcSourceValuePartialReceipts.receiptId(f.ref.ownerId());f.db.jdbc.update("UPDATE jobs SET operator_id='fictional-wrong-role' WHERE id=?",receipt);assertThrows(RuntimeException.class,()->verify(captured));f.db.jdbc.update("UPDATE jobs SET operator_id=? WHERE id=?",JdbcSourceValuePartialReceipts.ACTOR,receipt);assertNotNull(verify(captured));int rows=f.db.count("1=1");assertThrows(RuntimeException.class,()->f.original.p1.tx(()->{service.verify(captured);throw new IllegalStateException("fictional downstream rollback");}));assertEquals(rows,f.db.count("1=1"));
    }
    @Test void StagedBytesMissingDedupPortsAndTransactionBoundariesCannotGrantAuthority()throws Exception{
        setup(false);q.p.service.stage(f.ref);assertNull(service.capture(f.ref));assertThrows(RuntimeException.class,()->f.original.read(()->service.capture(f.ref)));assertThrows(RuntimeException.class,()->f.original.p1.tx(()->service.capture(f.ref)));q.service.seal(f.ref);var captured=service.capture(f.ref);assertThrows(RuntimeException.class,()->service.verify(captured));assertThrows(RuntimeException.class,()->f.original.read(()->service.verify(captured)));service=provider(null);assertThrows(RuntimeException.class,()->service.capture(f.ref));assertThrows(RuntimeException.class,()->verify(captured));service=provider(f.authority.service);assertThrows(RuntimeException.class,()->service.capture(new FrozenSourceStagePlan.Reference(f.ref.ownerId(),"b".repeat(64),f.ref.indexHash())));assertThrows(RuntimeException.class,()->verify(null));
    }
    @Test void ConstructorsAreLazyAndNativeCapacityIsNotConvertedToAnOrdinaryFailure()throws Exception{
        var seals=mock(SourceValuePartialSealService.class);var resolutions=mock(SourceStageResolutionService.class);var archive=mock(JdbcSourceValuePartialBlocks.class);var receipts=mock(JdbcSourceValuePartialReceipts.class);var rootsMock=mock(JdbcSourceStageRoots.class);var dedup=mock(SourceDedupPartialDependencyPermitService.class);var tx=mock(org.springframework.transaction.PlatformTransactionManager.class);new SourceValuePartialCommitPermitService(seals,resolutions,archive,receipts,rootsMock,dedup,tx);verifyNoInteractions(seals,resolutions,archive,receipts,rootsMock,dedup,tx);setup(true);q.service.seal(f.ref);var captured=service.capture(f.ref);roots=spy(roots);doThrow(JdbcSourceStageRoots.CapacityRejected.class).when(roots).lockOriginal(anyList());service=provider(f.authority.service);assertThrows(GenerationFlowService.CapacityGuarded.class,()->verify(captured));
    }
}
